"use strict";(()=>{var t="https://offolab.com";chrome.runtime.onMessage.addListener((e,n,o)=>{if(e.type==="open_receipt"){let r=encodeURIComponent(e.url);chrome.tabs.create({url:`${t}/receipt?url=${r}&ext=true`})}});chrome.runtime.onInstalled.addListener(e=>{e.reason==="install"&&(chrome.tabs.create({url:`${t}/extension?installed=true`}),chrome.storage.local.set({enabled:!0}))});})();
